-- ---------------------------------------------------------------------------
-- Post-conditions: abort if the snapshot did not land exactly.
-- ---------------------------------------------------------------------------
DO $$
DECLARE n_total int; n_formal int; n_app int; n_dir int; n_vis int; n_emcs int;
BEGIN
  SELECT count(*) INTO n_total  FROM iam_navigation_menu;
  SELECT count(*) INTO n_formal FROM iam_navigation_menu WHERE nav_eligible = 1;
  SELECT count(*) INTO n_app    FROM iam_navigation_menu WHERE menu_kind = 'APP';
  SELECT count(*) INTO n_dir    FROM iam_navigation_menu WHERE menu_kind = 'DIRECTORY';
  SELECT count(*) INTO n_vis    FROM iam_navigation_menu WHERE menu_kind = 'PAGE' AND visible = 1;
  SELECT count(*) INTO n_emcs   FROM iam_navigation_menu
   WHERE last_batch_id = 'BATCH_EMCS_HIDE_20261020' AND visible = 0;

  IF n_total  <> 90 THEN RAISE EXCEPTION 'expected 90 menu rows, got %', n_total; END IF;
  IF n_formal <>  7 THEN RAISE EXCEPTION 'expected 7 formal pages, got %', n_formal; END IF;
  IF n_app    <>  8 THEN RAISE EXCEPTION 'expected 8 apps, got %', n_app; END IF;
  IF n_dir    <> 15 THEN RAISE EXCEPTION 'expected 15 directories, got %', n_dir; END IF;
  IF n_vis    <> 48 THEN RAISE EXCEPTION 'expected 48 visible pages, got %', n_vis; END IF;
  IF n_emcs   <> 16 THEN RAISE EXCEPTION 'expected 16 hidden EMCS rows, got %', n_emcs; END IF;
END $$;

COMMIT;
